<a class="btn btn-outline-secondary mb-3" href="<?= BASE_URL ?>/academy/course?id=<?= (int)$course['id'] ?>">Volver al curso</a><h1 class="h3"><?= e($exam['titulo']) ?></h1><p class="text-muted"><?= e($course['titulo']) ?></p><p>Nota mínima: <strong><?= e($exam['nota_minima']) ?>/20</strong> · Intentos usados: <?= count($attempts) ?> de <?= Assessment::MAX_ATTEMPTS ?></p>
<?php if ($errors): ?><div class="alert alert-danger" role="alert"><ul class="mb-0"><?php foreach ($errors as $error): ?><li><?= e($error) ?></li><?php endforeach; ?></ul></div><?php endif; ?>
<?php if ($certificate): ?><div class="alert alert-success">Ya aprobaste el curso. <a href="<?= BASE_URL ?>/academy/certificate?code=<?= e($certificate['codigo']) ?>">Ver mi certificado</a></div><?php elseif ($progress['percent']!==100 || !$progress['total']): ?><div class="alert alert-info">Completa todas las lecciones para habilitar el examen.</div><?php elseif (!$canSubmit): ?><div class="alert alert-warning">Ya no hay intentos disponibles para esta evaluación.</div><?php endif; ?>
<?php if ($attempts): ?><section class="card card-body mb-4"><h2 class="h5">Mis intentos</h2><?php foreach ($attempts as $index=>$attempt): ?><div class="border-top py-2">Intento <?= $index+1 ?> · <?= e($attempt['nota']) ?>/20 · <?= $attempt['aprobada'] ? 'Aprobado' : 'No aprobado' ?> · <a href="<?= BASE_URL ?>/academy/exam/result?id=<?= (int)$attempt['id'] ?>">Ver resultado</a></div><?php endforeach; ?></section><?php endif; ?>
<?php if ($canSubmit): ?><form method="post" action="<?= BASE_URL ?>/academy/exam/submit?course_id=<?= (int)$course['id'] ?>" onsubmit="return confirm('¿Enviar tus respuestas? Se consumirá un intento.')"><?= Csrf::field() ?><input type="hidden" name="version" value="<?= (int)$exam['version'] ?>"><input type="hidden" name="submission_key" value="<?= e($submissionKey) ?>">
<?php foreach ($questions as $index=>$question): ?><fieldset class="card card-body mb-3"><legend class="h5 float-none w-auto"><?= $index+1 ?>. <?= e($question['enunciado']) ?></legend><?php foreach (['a','b','c','d'] as $option): if (($question['opcion_'.$option] ?? '')==='') continue; ?><div class="form-check mb-2"><input class="form-check-input" type="radio" id="q<?= (int)$question['id'] ?>-<?= e($option) ?>" name="answers[<?= (int)$question['id'] ?>]" value="<?= e($option) ?>" required <?= ($answers[$question['id']] ?? null)===$option ? 'checked' : '' ?>><label class="form-check-label" for="q<?= (int)$question['id'] ?>-<?= e($option) ?>"><?= e(strtoupper($option).'. '.$question['opcion_'.$option]) ?></label></div><?php endforeach; ?></fieldset><?php endforeach; ?><button class="btn btn-primary">Enviar examen</button></form><?php endif; ?>
